begin;

-- The authored home remains canonical. A private per-account location is only
-- an adapter for the existing UUID-based plan, scene and media systems.
alter table public.together_character_homes
  add column if not exists visits_enabled boolean not null default false,
  add column if not exists personal_details jsonb not null default '[]',
  add column if not exists possible_activities text[] not null default array['Have coffee','Cook together','Watch something','Just hang out'],
  add column if not exists approved_artwork_id uuid,
  add column if not exists invitation_config jsonb not null default '{"enabled":true,"cooldownDays":7,"scenarioCooldownDays":30}';

create table if not exists public.together_home_artwork (
  id uuid primary key default gen_random_uuid(),
  home_id uuid not null references public.together_character_homes(id) on delete cascade,
  status text not null default 'queued' check(status in ('queued','generating','ready','failed')),
  prompt_text text not null,
  storage_bucket text not null default 'kivelli-home-artwork',
  storage_path text,
  thumbnail_path text,
  width integer, height integer,
  provider text, model text, cost_usd numeric,
  error_code text,
  requested_by uuid references auth.users(id) on delete set null,
  lease_until timestamptz,
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  check(status <> 'ready' or (storage_path is not null and width > 0 and height > 0))
);
create index if not exists together_home_artwork_home_idx on public.together_home_artwork(home_id,created_at desc);
create unique index if not exists together_home_artwork_one_job_idx on public.together_home_artwork(home_id) where status in ('queued','generating');
alter table public.together_home_artwork enable row level security;
revoke all on public.together_home_artwork from anon, authenticated;
grant all on public.together_home_artwork to service_role;
alter table public.together_character_homes add constraint together_character_homes_artwork_fk foreign key(approved_artwork_id) references public.together_home_artwork(id) on delete set null;

alter table public.together_locations add column if not exists character_home_id uuid references public.together_character_homes(id) on delete restrict;
alter table public.together_locations add constraint together_home_location_private check(character_home_id is null or owner_user_id is not null);
create unique index if not exists together_home_location_owner_idx on public.together_locations(owner_user_id,character_home_id) where character_home_id is not null;
create index if not exists together_home_location_home_idx on public.together_locations(character_home_id) where character_home_id is not null;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('kivelli-home-artwork','kivelli-home-artwork',true,15000000,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
-- Catalog interiors are public, non-personal artwork. Uploads use service_role;
-- there are intentionally no anonymous/authenticated write policies.

create or replace function public.kivelle_limit_private_places()
returns trigger language plpgsql set search_path=public as $$
declare place_limit integer;
begin
  if new.owner_user_id is null or new.archived_at is not null or new.character_home_id is not null then return new; end if;
  if tg_op='UPDATE' and old.owner_user_id=new.owner_user_id and old.archived_at is null then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended(new.owner_user_id::text,0));
  select case when e.expires_at is not null and e.expires_at<=current_timestamp then 3
    when e.tier='kivelle_max' then 50 when e.tier='kivelle_plus' then 20 else 3 end
    into place_limit from public.together_entitlements e where e.user_id=new.owner_user_id;
  if (select count(*) from public.together_locations where owner_user_id=new.owner_user_id and archived_at is null and character_home_id is null and id<>new.id)>=coalesce(place_limit,3)
    then raise exception 'Private place limit reached' using errcode='23514'; end if;
  return new;
end $$;

create or replace function public.kivelle_guard_home_projection()
returns trigger language plpgsql set search_path=public as $$
begin
  if ((tg_op<>'DELETE' and new.character_home_id is not null) or (tg_op<>'INSERT' and old.character_home_id is not null))
    and current_user not in ('postgres','service_role','supabase_admin') and coalesce(auth.role(),'')<>'service_role'
    then raise exception 'Character homes are managed by the server' using errcode='42501'; end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;
create trigger kivelle_guard_home_projection before insert or update or delete on public.together_locations for each row execute function public.kivelle_guard_home_projection();

create or replace function public.kivelle_ensure_home_location(p_user_id uuid,p_character_instance_id uuid)
returns public.together_locations language plpgsql security definer set search_path=public as $$
declare h public.together_character_homes; place public.together_locations; art public.together_home_artwork;
begin
  select home.* into h from public.together_character_homes home
    join public.together_character_instances i on i.character_version_id=home.character_version_id
    join public.together_profiles p on p.user_id=i.user_id and p.active_continuity_id=i.continuity_id
    where i.id=p_character_instance_id and i.user_id=p_user_id and home.active and home.visits_enabled;
  if not found then raise exception 'Home unavailable' using errcode='P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text||h.id::text,0));
  select * into art from public.together_home_artwork where id=h.approved_artwork_id and home_id=h.id and status='ready';
  insert into public.together_locations(id,owner_user_id,character_home_id,world_id,parent_location_id,depth,name,slug,description,category,location_type,hours,possible_activities,canonical_visual_context,canonical_lore,metadata,sort_order)
  values(gen_random_uuid(),p_user_id,h.id,h.world_id,h.district_anchor_location_id,case when h.district_anchor_location_id is null then 0 else 1 end,h.name,'home-visit-'||gen_random_uuid(),h.description,'home','residence','{"open":"00:00","close":"24:00"}',h.possible_activities,
    h.canonical_visual_context||jsonb_build_object('canonicalPrompt',h.prompt_text),h.canonical_lore||jsonb_build_object('homeId',h.id,'personalDetails',h.personal_details),
    jsonb_build_object('private',true,'directoryVisibility','private','userCreated',false,'kind','character_home','homeCharacterVersionId',h.character_version_id,'homeId',h.id,'artworkBucket',art.storage_bucket,'artworkPath',art.storage_path,'thumbnailPath',art.thumbnail_path),9999)
  on conflict(owner_user_id,character_home_id) where character_home_id is not null do update set
    name=excluded.name,description=excluded.description,possible_activities=excluded.possible_activities,
    canonical_visual_context=excluded.canonical_visual_context,canonical_lore=excluded.canonical_lore,metadata=excluded.metadata,updated_at=now()
  returning * into place;
  if art.id is not null then
    update public.together_media_reference_assets set active=(storage_path=art.storage_path and storage_bucket=art.storage_bucket) where location_id=place.id and asset_role='location_canonical';
    if not exists(select 1 from public.together_media_reference_assets where location_id=place.id and asset_role='location_canonical' and storage_path=art.storage_path and active) then
      insert into public.together_media_reference_assets(asset_role,location_id,source_key,storage_bucket,storage_path,content_type,width,height,revision,metadata)
      values('location_canonical',place.id,'character-home:'||h.id||':visit:'||place.id||':art:'||art.id,art.storage_bucket,art.storage_path,case when art.storage_path like '%.png' then 'image/png' when art.storage_path like '%.webp' then 'image/webp' else 'image/jpeg' end,art.width,art.height,1,jsonb_build_object('homeId',h.id,'artworkId',art.id));
    end if;
  end if;
  return place;
end $$;
revoke all on function public.kivelle_ensure_home_location(uuid,uuid) from public,anon,authenticated;
grant execute on function public.kivelle_ensure_home_location(uuid,uuid) to service_role;

create table public.together_home_invitations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  character_instance_id uuid not null references public.together_character_instances(id) on delete cascade,
  home_id uuid not null references public.together_character_homes(id) on delete cascade,
  conversation_id uuid not null references public.together_conversations(id) on delete cascade,
  action_id uuid references public.together_conversation_actions(id) on delete set null,
  activity_key text not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null
);
create index together_home_invitations_history_idx on public.together_home_invitations(user_id,character_instance_id,created_at desc);
create index together_home_invitations_home_idx on public.together_home_invitations(home_id);
create index together_home_invitations_conversation_idx on public.together_home_invitations(conversation_id);
create index together_home_invitations_action_idx on public.together_home_invitations(action_id);
alter table public.together_home_invitations enable row level security;
revoke all on public.together_home_invitations from anon,authenticated;
grant all on public.together_home_invitations to service_role;

create or replace function public.kivelle_offer_home_visit(p_user_id uuid,p_instance_id uuid,p_conversation_id uuid,p_user_message_id uuid,p_assistant_message_id uuid,p_home_id uuid,p_activity_key text,p_expires_at timestamptz,p_payload jsonb)
returns uuid language plpgsql security definer set search_path=public as $$
declare action_id uuid; continuity_id uuid; config jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('home-invite:'||p_user_id::text,0));
  select c.continuity_id into continuity_id from public.together_conversations c
    join public.together_profiles p on p.user_id=c.user_id and p.active_continuity_id=c.continuity_id
    where c.id=p_conversation_id and c.user_id=p_user_id and c.character_instance_id=p_instance_id and c.archived_at is null;
  if not found then return null; end if;
  if not exists(select 1 from public.together_messages where id=p_user_message_id and user_id=p_user_id and conversation_id=p_conversation_id and role='user' and created_at>now()-interval '2 minutes') then return null; end if;
  if not exists(select 1 from public.together_messages where id=p_assistant_message_id and user_id=p_user_id and conversation_id=p_conversation_id and role='assistant') then return null; end if;
  select h.invitation_config into config from public.together_character_homes h
    join public.together_character_instances i on i.character_version_id=h.character_version_id
    where h.id=p_home_id and h.active and h.visits_enabled and i.id=p_instance_id and i.user_id=p_user_id;
  if not found or config->>'enabled'='false' then return null; end if;
  if p_expires_at<=now() then return null; end if;
  if exists(select 1 from public.together_home_invitations where user_id=p_user_id and
    (created_at>now()-interval '24 hours' or (character_instance_id=p_instance_id and
      (created_at>now()-make_interval(days=>greatest(7,coalesce((config->>'cooldownDays')::int,7))) or
       (activity_key=p_activity_key and created_at>now()-make_interval(days=>greatest(30,coalesce((config->>'scenarioCooldownDays')::int,30)))))))) then return null; end if;
  if exists(select 1 from public.together_conversation_actions where user_id=p_user_id and conversation_id=p_conversation_id and status='pending' and expires_at>now()) then return null; end if;
  insert into public.together_conversation_actions(user_id,continuity_id,character_instance_id,conversation_id,assistant_message_id,candidate_type,status,payload,confidence,expires_at)
  values(p_user_id,continuity_id,p_instance_id,p_conversation_id,p_assistant_message_id,'plan_create','pending',p_payload,1,p_expires_at) returning id into action_id;
  insert into public.together_home_invitations(user_id,character_instance_id,conversation_id,home_id,activity_key,action_id,expires_at)
  values(p_user_id,p_instance_id,p_conversation_id,p_home_id,p_activity_key,action_id,p_expires_at);
  insert into public.together_conversation_events(user_id,continuity_id,character_instance_id,conversation_id,event_type,entity_type,entity_id,metadata)
  values(p_user_id,continuity_id,p_instance_id,p_conversation_id,'plan_proposed','conversation_action',action_id,p_payload||'{"candidateType":"plan_create","resolution":"pending"}'::jsonb);
  return action_id;
end $$;
revoke all on function public.kivelle_offer_home_visit(uuid,uuid,uuid,uuid,uuid,uuid,text,timestamptz,jsonb) from public,anon,authenticated;
grant execute on function public.kivelle_offer_home_visit(uuid,uuid,uuid,uuid,uuid,uuid,text,timestamptz,jsonb) to service_role;







